    if (scenarioPicker) scenarioPicker.hidden = data.scenarioPickerEnabled === false;
    if (missionPicker) { missionPicker.hidden = data.scenarioPickerEnabled !== false; missionPicker.value = data.selectedMission || 'C1'; }
