  function accountMenu(initials, name, meta, switchLabel, switchContext) {
    const switchAction = switchLabel ? `<button type="button" data-action="switch-context" data-context="${switchContext}">${switchLabel}</button>` : '';
    const role = currentUser()?.role;
    const profileAction = ['client', 'carrier'].includes(role) ? `<button type="button" data-route="${role}-profile">Mi perfil</button>` : '';
    return `<details class="account-menu"><summary class="account-chip"><span>${initials}</span><span><small>${escapeHtml(meta)}</small>${escapeHtml(name)}</span><span class="account-chevron" aria-hidden="true">⌄</span></summary><div class="account-menu-panel">${profileAction}${switchAction}<button type="button" data-action="logout">Cerrar sesión</button></div></details>`;
  }
