  function pageHeading(eyebrow, title, description = '', actions = '') { return `<section class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${description ? `<p>${description}</p>` : ''}</div>${actions ? `<div class="page-actions">${actions}</div>` : ''}</section>`; }
  function examplePlaceholders(markup) { return markup.replace(/placeholder="(?=[^"])(?!Ej\.)/g, 'placeholder="Ej. '); }
  function viewShell(content, className = '') { return `<div class="shell workspace ${className}">${examplePlaceholders(content)}</div>`; }
