      const requiredDocs = [...(review.docs || [])].filter((doc) => !doc.startsWith('Certificado de situación censal AEAT') && !doc.startsWith('Autorización de Transporte') && !doc.startsWith('Seguro de Mercancías'));
      review.docs = [...requiredDocs, aeat ? `Certificado de situación censal AEAT · ${aeat.name}` : (review.docs || []).find((doc) => doc.startsWith('Certificado de situación censal AEAT')) || 'Certificado de situación censal AEAT', authorization ? `Autorización de Transporte · ${authorization.name}` : (review.docs || []).find((doc) => doc.startsWith('Autorización de Transporte')) || 'Autorización de Transporte'];
      if (insurance || review.insurance) review.docs.push(insurance ? `Seguro de Mercancías · ${insurance.name}` : (review.docs || []).find((doc) => doc.startsWith('Seguro de Mercancías')) || 'Seguro de Mercancías'); review.insurance = Boolean(insurance) || review.insurance; if (otherFiles.length) review.otherDocs = otherFiles.map((file) => file.name); persist(); render(); toast('Documentación actualizada. El estado del alta no ha cambiado.', 'success');
